,.estimate-section td:nth-child(2),.estimate-section td:nth-child(3),.estimate-section td:nth-child(4){text-align:right}.estimate-total{width:55%;margin:15px 0 0 auto}.estimate-total div{display:flex;justify-content:space-between;border-bottom:1px solid #eaecf0;padding:7px}.estimate-total .grand{border-top:2px solid #092b52;border-bottom:0;color:#155eef;font-size:16px;font-weight:bold}.estimate-footer{margin-top:24px;padding-top:12px;border-top:1px dashed #98a2b3;text-align:center;color:#475467;white-space:pre-line}.estimate-signature{margin-top:34px;text-align:right;color:#475467}
