</style></head><body><div class="print-toolbar"><a href="index.php?page=admin&amp;section=estimates">Back to Estimates</a><span><a href="index.php?page=admin&amp;section=estimates-print-settings">Edit Header / Footer</a> <button type="button" onclick="window.print()">Print A4 Estimate</button></span></div><main class="estimate-paper"><header class="estimate-brand"><h1><?= e($s['garage_name']) ?></h1><?php if($s['tagline']): ?><p><?= e($s['tagline']) ?></p><?php endif; ?><?php if($s['address']): ?><small><?= nl2br(e($s['address'])) ?></small><?php endif; ?><?php if($s['contact_number'] || $s['email']): ?><small><?= e(trim($s['contact_number'].' '.($s['email'] ? ' | '.$s['email'] : ''))) ?></small><?php endif; ?></header><?php if($s['receipt_header']): ?><div class="estimate-note"><?= nl2br(e($s['receipt_header'])) ?></div><?php endif; ?><div class="estimate-title"><h2>ESTIMATE</h2><span>Thank you for choosing us</span></div><section class="estimate-meta"><div><span>Estimate No.</span><strong><?= e($estimate['estimate_no']) ?></strong></div><div><span>Estimate Date</span><strong><?= e($estimate['estimate_date']) ?></strong></div><div><span>Customer</span><strong><?= e($estimate['customer_name']) ?></strong></div><div><span>Valid Until</span><strong><?= e($estimate['valid_until']) ?></strong></div><div><span>Contact</span><strong><?= e($estimate['contact_number']) ?></strong></div><div><span>Vehicle</span><strong><?= e($estimate['vehicle_number'] ?: '-') ?></strong></div><div><span>Service / Issue</span><strong><?= e($estimate['service_type']) ?></strong></div><div><span>Mileage</span><strong><?= $estimate['mileage'] !== null ? e(number_format((float)$estimate['mileage'], 2).' KM') : '-' ?></strong></div></section><section class="estimate-section"><h3>Estimate Items</h3><table><thead><tr><th>#</th><th>Description</th><th>Qty</th><th>Amount (Rs.)</th></tr></thead><tbody><?php foreach($estimate['items'] as $index=>$item): ?><tr><td><?= $index+1 ?></td><td><?= e($item['item_name']) ?></td><td><?= number_format((float)$item['quantity'], 2) ?></td><td><?= number_format((float)$item['amount'], 2) ?></td></tr><?php endforeach; ?></tbody></table></section><div class="estimate-total"><div><span>Subtotal</span><strong>Rs. <?= number_format((float)$estimate['subtotal'], 2) ?></strong></div><div><span>Discount</span><strong>Rs. <?= number_format((float)$estimate['discount'], 2) ?></strong></div><div><span>VAT (<?= number_format((float)$estimate['vat_rate'], 2) ?>%)</span><strong>Rs. <?= number_format((float)$estimate['vat_amount'], 2) ?></strong></div><div class="grand"><span>Total Amount</span><strong>Rs. <?= number_format((float)$estimate['total_amount'], 2) ?></strong></div></div><?php if($estimate['notes']): ?><div class="estimate-section"><h3>Notes</h3><div class="estimate-note"><?= nl2br(e($estimate['notes'])) ?></div></div><?php endif; ?><div class="estimate-signature">Authorized Signature: ____________________</div><?php if($s['receipt_footer']): ?><footer class="estimate-footer"><?= nl2br(e($s['receipt_footer'])) ?></footer><?php endif; ?></main><script>window.addEventListener('load',function(){setTimeout(function(){window.print();},350);});</script></body></html>
